 1→//! Shell command execution and environment management.
 2→
 3→pub mod command;
 4→pub mod debug;
 5→pub mod platform;
 6→pub mod refresh;
 7→pub mod resume;
 8→
 9→pub use command::{
10→    execute, execute_check, execute_quiet, execute_streaming, CommandOptions, CommandResult,
11→    OutputCallback, OutputLine,
12→};
13→pub use platform::{detect_shell, is_ci, is_elevated, ShellInfo, ShellType};
14→pub use refresh::{PathChangeDetector, PathChangeResult, ShellReloadInfo};
15→pub use resume::{ReloadChoice, ResumeState};
