fn make_step_with_check(
    name: &str,
    command: &str,
    check: Option<crate::config::CompletedCheck>,
) -> ResolvedStep {
    ResolvedStep {
        name: name.to_string(),
        title: name.to_string(),
        description: None,
        command: command.to_string(),
        depends_on: vec![],
        completed_check: check,
        precondition: None,
        skippable: true,
        required: false,
        prompt_if_complete: true,
        allow_failure: false,
        retry: 0,
        env: HashMap::new(),
        watches: vec![],
        before: vec![],
        after: vec![],
        sensitive: false,
        requires_sudo: false,
        requires: vec![],
        only_environments: vec![],
    }
}

#[test]
fn run_with_ui_executes_simple_step() {
    let temp = TempDir::new().unwrap();
    let marker = temp.path().join("ran.txt");

    let config: BivvyConfig = serde_yaml::from_str(
        r#"
        workflows:
          default:
            steps: [hello]
    "#,
    )
    .unwrap();

    let mut steps = HashMap::new();
    steps.insert(
        "hello".to_string(),
        make_step("hello", &format!("touch {}", marker.display()), vec![]),
    );

    let runner = WorkflowRunner::new(&config, steps);
    let options = RunOptions::default();
    let ctx = InterpolationContext::new();

    let mut ui = MockUI::new();
    ui.set_interactive(true);

    let result = runner
        .run_with_ui(
            &options,
            &ctx,
            &HashMap::new(),
            temp.path(),
            false,
            &HashMap::new(),
            None,
            &mut ui,
        )
        .unwrap();

    assert!(result.success);
    assert_eq!(result.steps.len(), 1);
    assert!(!result.steps[0].skipped);
    // Verify the command actually ran
    assert!(
        marker.exists(),
        "step command should have created marker file"
    );
}

