        let config: BivvyConfig = serde_yaml::from_str(
            r#"
            workflows:
              default:
                steps: [hello]
        "#,
        )
        .unwrap();

        let mut steps = HashMap::new();
        steps.insert(
            "hello".to_string(),
            make_step("hello", "echo hello", vec![]),
        );

        let runner = WorkflowRunner::new(&config, steps);
        let options = RunOptions {
            dry_run: true,
            ..Default::default()
        };
        let ctx = InterpolationContext::new();
        let mut ui = MockUI::new();
        ui.set_interactive(true);

        runner
            .run_with_ui(
                &options,
                &ctx,
                &HashMap::new(),
                temp.path(),
                false,
                &HashMap::new(),
                None,
                &mut ui,
            )
            .unwrap();

        assert!(
            ui.prompts_shown().is_empty(),
            "dry-run should not show interactive prompts, but showed: {:?}",
            ui.prompts_shown()
        );
    }
}

